window.AJSportProfiles = {"general":[{"claim":"Across randomised trials, strength training cut sports injuries to under a third (RR 0.32) and nearly halved overuse injuries; it was far more protective than stretching.","source":"Lauersen, Bertelsen & Andersen 2014, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/48/11/871"},{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"},{"claim":"In professional footballers, one strength session a week in season maintained pre-season gains in strength and sprint speed, whereas one session every two weeks let them decline.","source":"Rønnestad, Nymark & Raastad 2011, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/21873897/"},{"claim":"Doing endurance and strength training together does not blunt muscle growth or maximal strength, but can blunt explosive strength, especially when both are done in the same session.","source":"Schumann et al. 2022, Sports Medicine","url":"https://researchonline.jcu.edu.au/71546/"},{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"},{"claim":"A Copenhagen adductor strengthening programme lowered the odds of groin problems by 41% in male football players.","source":"Harøy et al. 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/3/150"},{"claim":"The FIFA 11+ warm-up (running, strength, balance and plyometric work) reduced overall football injuries by 39%.","source":"Thorborg et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/7/562"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"},{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"},{"claim":"Strength training (resistance plus plyometrics, 2-3 times a week for 8-12 weeks) produced a large improvement in running economy in highly trained distance runners.","source":"Balsalobre-Fernández, Santos-Concejero & Grivas 2016, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/26694507/"},{"claim":"Adding heavy strength training to endurance training improves running and cycling economy and performance, with heavy strength work giving the clearest benefit for cyclists.","source":"Rønnestad & Mujika 2014, Scandinavian Journal of Medicine & Science in Sports","url":"https://doi.org/10.1111/sms.12104"},{"claim":"Gains in lower-body (squat) strength transfer to sprint performance, with strength gains strongly correlated with sprint improvements.","source":"Seitz et al. 2014, Sports Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/25059334/"}],"sports":[{"id":"tennis","name":"Tennis","aliases":["lawn tennis","tennis doubles","tennis singles"],"group":"Racket","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","elbow","ankle","calf","trunkLat","copenhagen"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated short explosive rallies of a few seconds with brief recovery between points, over matches that can last hours.","summary":"Tennis is short explosive rallies with lots of rotation and overhead hitting. The plan builds leg and rotational power, which a junior tennis study showed can raise serve speed, and adds rotator cuff work, which has cut shoulder problems in overhead athletes.","evidence":[{"claim":"A 6-week conditioning programme significantly increased serve velocity in junior tennis players, with no change in a control group.","source":"Fernandez-Fernandez et al. 2013, Journal of Sports Science and Medicine","url":"https://www.jssm.org/jssm-12-232.xml-abst"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"moderate"},{"id":"padel","name":"Padel","aliases":["paddle tennis","padel tennis"],"group":"Racket","q":{"maxStrength":2,"power":2,"rotational":3,"unilateral":3,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":2,"mass":1},"prehab":["calf","elbow","shoulderER","lowback","ankle","copenhagen"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Short repeated rallies with quick lateral moves and lots of overhead and wall play.","summary":"Padel combines quick lateral footwork with overhead smashes and rotational shots. The plan builds leg strength and rotational power and adds shoulder and ankle work, borrowed from tennis and court-sport research because padel-specific studies are scarce.","evidence":[{"claim":"Across studies, average heart rate in padel match play is about 70-80% of maximum.","source":"Physiological demands of padel: mini review 2023, Frontiers in Sports and Active Living","url":"https://frontiersin.org/articles/10.3389/fspor.2023.1284063/full"},{"claim":"Padel injury surveys most often report the elbow, lower back, shoulder, knee, calf and ankle, and most injuries are overuse.","source":"Performance requirements and injury incidence of padel: a narrative review","url":"https://kimuk.conare.ac.cr/Record/PUCR_b22a95b01f153099df0c1de59e57a8b1"}],"confidence":"limited"},{"id":"squash","name":"Squash","aliases":["doubles squash","squash rackets"],"group":"Racket","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":2,"neck":0,"trunk":2,"mass":1},"prehab":["calf","copenhagen","ankle","lowback","shoulderER","elbow"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"High-intensity rallies with repeated lunges and sharp changes of direction, demanding both aerobic fitness and repeated sprint ability.","summary":"Squash is relentless lunging and turning in a small court. The plan builds single-leg strength and power for lunging and adds balance and landing work, which reduce ankle and knee injuries in court sports.","evidence":[{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"}],"confidence":"limited"},{"id":"badminton","name":"Badminton","aliases":["badders","shuttlecock"],"group":"Racket","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":3,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["calf","ankle","patellar","landing","shoulderER","copenhagen"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Very short, explosive rallies with jumps, lunges and fast recovery between points.","summary":"Badminton is explosive jumping, lunging and overhead hitting. The plan builds leg power and single-leg strength and adds landing, ankle and rotator cuff work, which have been shown to reduce knee, ankle and shoulder problems in jumping and overhead sports.","evidence":[{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"limited"},{"id":"tabletennis","name":"Table tennis","aliases":["ping pong","ping-pong","TT"],"group":"Racket","q":{"maxStrength":1,"power":2,"rotational":3,"unilateral":2,"upperPull":1,"upperPush":1,"lowerBody":2,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["shoulderER","lowback","trunkLat","elbow","ankle"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":null,"energy":"Very short rallies with rapid footwork and repeated fast rotation of the trunk.","summary":"Table tennis needs quick feet and fast trunk rotation rather than raw strength. The plan uses moderate strength work with rotational power and shoulder and back resilience work; sport-specific strength research is limited.","evidence":[],"confidence":"limited"},{"id":"pickleball","name":"Pickleball","aliases":["pickle ball"],"group":"Racket","q":{"maxStrength":1,"power":1,"rotational":2,"unilateral":2,"upperPull":1,"upperPush":1,"lowerBody":2,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["ankle","calf","shoulderER","elbow","hipAbd"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":"lower","energy":"Short rallies with lots of quick small steps and reactive movement at the net.","summary":"Pickleball is short reactive rallies with lots of quick lateral steps. The plan focuses on general leg strength, balance and calf strength to protect ankles and Achilles, plus shoulder care, drawing on general injury-prevention research as pickleball studies are scarce.","evidence":[{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"}],"confidence":"limited"},{"id":"football","name":"Football (soccer)","aliases":["5-a-side","6-a-side","7-a-side","five-a-side","futsal","soccer"],"group":"Team field","q":{"maxStrength":3,"power":3,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":1,"trunk":2,"mass":1},"prehab":["nordic","copenhagen","landing","ankle","hipFlex","calf"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Intermittent running with repeated sprints, jumps and changes of direction over 90 minutes, on a strong aerobic base.","summary":"Football is repeated sprints, cuts and kicks over 90 minutes. The plan builds leg strength and speed and includes Nordic hamstring, Copenhagen adductor and landing work, which have each been shown to cut hamstring, groin and knee injuries in footballers.","evidence":[{"claim":"The FIFA 11+ warm-up (running, strength, balance and plyometric work) reduced overall football injuries by 39%.","source":"Thorborg et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/7/562"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"},{"claim":"A Copenhagen adductor strengthening programme lowered the odds of groin problems by 41% in male football players.","source":"Harøy et al. 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/3/150"},{"claim":"In professional footballers, one strength session a week in season maintained pre-season gains in strength and sprint speed, whereas one session every two weeks let them decline.","source":"Rønnestad, Nymark & Raastad 2011, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/21873897/"}],"confidence":"strong"},{"id":"rugbyunion","name":"Rugby union","aliases":["15s","7s","fifteens","rugby","rugby 7s","rugby sevens","rugby xv","sevens","women's rugby"],"group":"Team field","q":{"maxStrength":3,"power":3,"rotational":2,"unilateral":2,"upperPull":3,"upperPush":3,"lowerBody":3,"grip":2,"neck":3,"trunk":3,"mass":2},"prehab":["neck","nordic","shoulderER","landing","ankle","copenhagen"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Repeated high-intensity efforts of sprinting, tackling and rucking with short recoveries, on top of heavy contact.","summary":"Rugby demands strength, power and the ability to absorb repeated collisions. The plan prioritises heavy lifting and power, with neck strengthening and movement control work, which a large schools trial linked to fewer concussions and injuries.","evidence":[{"claim":"A pre-activity movement control warm-up (Activate) in schoolboy rugby was associated with fewer concussions, and teams doing it three or more times a week had 72% fewer match injuries.","source":"Hislop et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/15/1140"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"rugbyleague","name":"Rugby league","aliases":["13-a-side","league","nrl","rugby 13s","super league"],"group":"Team field","q":{"maxStrength":3,"power":3,"rotational":2,"unilateral":2,"upperPull":3,"upperPush":3,"lowerBody":3,"grip":2,"neck":3,"trunk":3,"mass":2},"prehab":["neck","nordic","shoulderER","landing","ankle"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Repeated sprints and tackles with short recoveries, with more running and tackling per player than union.","summary":"Rugby league is repeated tackling and sprinting with little rest. The plan builds heavy strength and power and adds neck and hamstring work, drawing on rugby union and contact-sport research showing these reduce concussion and hamstring injury.","evidence":[{"claim":"A pre-activity movement control warm-up (Activate) in schoolboy rugby was associated with fewer concussions, and teams doing it three or more times a week had 72% fewer match injuries.","source":"Hislop et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/15/1140"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"americanfootball","name":"American football","aliases":["gridiron","nfl","tackle football"],"group":"Team field","q":{"maxStrength":3,"power":3,"rotational":2,"unilateral":2,"upperPull":2,"upperPush":3,"lowerBody":3,"grip":2,"neck":3,"trunk":3,"mass":2},"prehab":["neck","nordic","landing","ankle","shoulderER","copenhagen"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Very short, maximal plays of a few seconds followed by long rests between downs.","summary":"American football is short, maximal bursts of collision and sprinting. The plan focuses on maximal strength and power and adds neck strengthening, since stronger necks are linked to fewer concussions, plus hamstring and landing work.","evidence":[{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"},{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"aussierules","name":"Australian rules football","aliases":["afl","aflw","aussie rules","australian football","footy"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":1,"neck":2,"trunk":3,"mass":1},"prehab":["nordic","copenhagen","landing","ankle","calf","neck","hipFlex"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"High running volumes with repeated sprints, jumps and contests over long matches.","summary":"Aussie rules combines long running distances with sprints, marking jumps and tackles. The plan builds leg strength and power with a strong emphasis on Nordic hamstring work, because AFL players with weak eccentric hamstrings are several times more likely to strain them.","evidence":[{"claim":"Australian footballers with low eccentric hamstring strength in preseason had a 2.7 to 4.3 times higher risk of hamstring strain.","source":"Opar et al. 2015, Medicine & Science in Sports & Exercise","url":"https://pubmed.ncbi.nlm.nih.gov/25137368/"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"gaelicfootball","name":"Gaelic football","aliases":["gaa","gaelic","ladies gaelic football","lgfa","peil"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":1,"neck":1,"trunk":2,"mass":1},"prehab":["nordic","copenhagen","landing","ankle","hipFlex"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Intermittent running with repeated sprints, jumps and physical contests.","summary":"Gaelic football is repeated sprints, catches and turns. The plan builds leg strength and power and includes landing and balance work like the GAA 15 warm-up, which improved landing technique in Gaelic players, plus Nordic hamstring work.","evidence":[{"claim":"The GAA 15 neuromuscular warm-up improved balance and landing technique (ACL risk markers) in Gaelic football and hurling players.","source":"O'Malley et al. 2017, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/27398918/"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"hurling","name":"Hurling","aliases":["camanachd","camogie","hurley","iomaint","shinty"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":1,"trunk":3,"mass":1},"prehab":["nordic","copenhagen","trunkLat","elbow","ankle","shoulderER"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Intermittent sprints and contests with powerful rotational striking.","summary":"Hurling mixes sprinting with fast rotational striking and contact. The plan builds leg and rotational power, adds grip strength and includes landing, balance and hamstring work shown to reduce lower-limb injury risk in Gaelic games and field sports.","evidence":[{"claim":"The GAA 15 neuromuscular warm-up improved balance and landing technique (ACL risk markers) in Gaelic football and hurling players.","source":"O'Malley et al. 2017, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/27398918/"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"moderate"},{"id":"fieldhockey","name":"Field hockey","aliases":["hockey","hockey5s","indoor hockey"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["ankle","nordic","lowback","copenhagen","landing","trunkLat","hipFlex"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated sprints in a crouched posture with quick changes of direction.","summary":"Hockey is repeated sprinting while bent over a stick. The plan builds leg strength and power, trunk and back endurance for the crouched posture, and hamstring and groin work borrowed from football research, as hockey-specific trials are limited.","evidence":[{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"},{"claim":"A Copenhagen adductor strengthening programme lowered the odds of groin problems by 41% in male football players.","source":"Harøy et al. 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/3/150"}],"confidence":"limited"},{"id":"lacrosse","name":"Lacrosse","aliases":["box lacrosse","field lacrosse","lax","sixes","women's lacrosse"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":2,"trunk":3,"mass":1},"prehab":["landing","ankle","nordic","neck","shoulderER","copenhagen"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Intermittent sprinting, cutting and shooting with some body contact.","summary":"Lacrosse involves sprinting, sharp cuts and rotational shooting. The plan builds leg and rotational power and adds landing and cutting work, which cuts ACL injury risk by about half in field and court sports.","evidence":[{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"}],"confidence":"limited"},{"id":"ultimate","name":"Ultimate frisbee","aliases":["beach ultimate","disc","frisbee","indoor ultimate","ultimate","ultimate frisbee"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":2,"mass":1},"prehab":["landing","nordic","ankle","calf","shoulderER"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated sprints and cuts on a high aerobic base: heart rate averages about 82% of max, and sprint output drops late in each half.","summary":"Ultimate is repeated sprints, hard cuts and jumps to catch, with knee, thigh and ankle injuries most common. The plan builds leg strength, speed and repeat-sprint fitness, and adds landing, hamstring, ankle and shoulder work.","evidence":[{"claim":"Male players covered about 4.7 km a game with 17 sprints, averaged 82% of max heart rate, and did 43-47% less high-intensity running late in each half.","source":"Krustrup & Mohr 2015, Journal of Strength and Conditioning Research","url":"https://test01.ku.dk/:obvius/pureproxy/3974268/en/publications/physical-demands-in-competitive-ultimate-frisbee"},{"claim":"The lower limb is most often injured, mainly the knee and thigh; muscle strains and joint sprains are the most common types.","source":"Fajardo Pulido & Lystad 2020, Sports","url":"https://doaj.org/article/235dc187d31246f58217b8c89f36d037"},{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"}],"confidence":"limited"},{"id":"cricket","name":"Cricket","aliases":["club cricket","fast bowling","indoor cricket","one-day cricket","T20","test cricket"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["trunkLat","lowback","nordic","calf","ankle","shoulderER"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Mostly low-intensity play punctuated by short explosive efforts: bowling run-ups, sprints between wickets and throws.","summary":"Cricket needs explosive, rotational power for bowling, batting and throwing. The plan builds leg and rotational power with back and shoulder resilience work, based on general throwing and injury-prevention research because cricket-specific strength trials are limited.","evidence":[{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"limited"},{"id":"baseball","name":"Baseball / softball","aliases":["fastpitch","fastpitch softball","rounders","slowpitch","softball"],"group":"Team field","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":2,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","elbow","trunkLat","nordic"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"upper","energy":"Brief maximal efforts (throwing, swinging, sprinting) separated by long rests.","summary":"Baseball and softball are short, explosive throws, swings and sprints. The plan builds rotational and leg power and adds shoulder and forearm care, as prevention programmes have been shown to reduce shoulder and elbow throwing injuries.","evidence":[{"claim":"A warm-up programme of stretching, mobility and balance exercises reduced shoulder and elbow throwing injuries in youth baseball players.","source":"Sakata et al. 2019, American Journal of Sports Medicine","url":"https://doi.org/10.1177/0363546519861378"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"moderate"},{"id":"basketball","name":"Basketball","aliases":["3x3","3x3 basketball","hoops","streetball"],"group":"Team court","q":{"maxStrength":2,"power":3,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["ankle","landing","patellar","calf","hipAbd","copenhagen","lowback"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated sprints, jumps and changes of direction with short recoveries.","summary":"Basketball is constant jumping, landing and cutting. The plan builds leg strength and jump power and adds landing and balance work, which have been shown to cut ACL injuries and ankle sprains.","evidence":[{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"},{"claim":"A balance training programme reduced ankle sprains in high school basketball and football (soccer) players (1.13 vs 1.87 per 1,000 exposures).","source":"McGuine & Keene 2006, American Journal of Sports Medicine","url":"https://www.aafp.org/pubs/afp/issues/2006/1115/p1777.html"}],"confidence":"strong"},{"id":"netball","name":"Netball","aliases":["men's netball","mixed netball"],"group":"Team court","q":{"maxStrength":2,"power":3,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["landing","ankle","nordic","calf","hipAbd","patellar"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Short repeated sprints, jumps and sudden stops, with frequent single-leg landings.","summary":"Netball is full of sudden stops and single-leg landings. The plan builds leg strength and power and puts landing and balance work at the centre, because neuromuscular training cuts non-contact ACL injuries in female athletes by around two thirds.","evidence":[{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"},{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"}],"confidence":"moderate"},{"id":"volleyball","name":"Volleyball","aliases":["beach volley","beach volleyball","indoor volleyball","volley"],"group":"Team court","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":2,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":1,"neck":0,"trunk":2,"mass":1},"prehab":["ankle","shoulderER","patellar","landing","lowback","calf"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Short explosive rallies with repeated maximal jumps and long breaks between points.","summary":"Volleyball is repeated maximal jumping and overhead hitting. The plan builds jump power and adds balance, landing and rotator cuff work, which have been shown to reduce ankle sprains in volleyball and shoulder problems in overhead athletes.","evidence":[{"claim":"Balance board training reduced ankle sprains in volleyball players, mainly in those with a previous sprain.","source":"Verhagen et al. 2004, American Journal of Sports Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/15310562/"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"strong"},{"id":"handball","name":"Handball","aliases":["beach handball","olympic handball","team handball"],"group":"Team court","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","landing","ankle","nordic","copenhagen"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated sprints, jumps and throws with contact and short recoveries.","summary":"Handball combines jumping, cutting, contact and powerful throwing. The plan builds leg and rotational power and adds a rotator cuff programme, which cut shoulder problems by 28% in elite handball players, plus landing work for the knees.","evidence":[{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"},{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"}],"confidence":"strong"},{"id":"icehockey","name":"Ice hockey","aliases":["EIHL","hockey on ice","ice-hockey","NHL"],"group":"Team court","q":{"maxStrength":3,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":2,"trunk":3,"mass":2},"prehab":["copenhagen","neck","hipAbd","hipFlex","shoulderER","lowback"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"all","energy":"Very intense shifts of 30-60 seconds with long rests on the bench, plus body contact.","summary":"Ice hockey is short, all-out shifts with powerful skating strides and contact. The plan builds leg strength and power and includes adductor strengthening, which cut groin strains by about four-fifths in professional hockey players.","evidence":[{"claim":"A preseason adductor strengthening programme in professional ice hockey cut adductor strains from 3.2 to 0.71 per 1,000 game exposures.","source":"Tyler et al. 2002, American Journal of Sports Medicine","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4223288"},{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"}],"confidence":"moderate"},{"id":"mma","name":"MMA","aliases":["cage fighting","mixed martial arts","UFC"],"group":"Combat","q":{"maxStrength":3,"power":3,"rotational":3,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":3,"grip":3,"neck":3,"trunk":3,"mass":0},"prehab":["neck","shoulderER","lowback","fingers","copenhagen"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Repeated high-intensity bursts of striking and grappling over 3-5 minute rounds.","summary":"MMA needs both grappling strength and fast striking power while staying within a weight class. The plan builds strength and power relative to body weight, with neck and grip work, reflecting research that stronger, more powerful fighters perform better.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"}],"confidence":"moderate"},{"id":"boxing","name":"Boxing","aliases":["amateur boxing","pro boxing","white collar boxing"],"group":"Combat","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":2,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":1,"neck":3,"trunk":3,"mass":0},"prehab":["neck","shoulderER","wrist","tspine"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"all","energy":"Repeated short bursts of punching and movement over 2-3 minute rounds with short rests.","summary":"Boxing relies on fast, rotational punching power and the ability to take a punch while making weight. The plan focuses on leg-to-trunk power and neck strength rather than bulk, based on combat-sport research linking power to performance level.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"}],"confidence":"moderate"},{"id":"kickboxing","name":"Kickboxing / Muay Thai","aliases":["full contact","k-1","k1","kickboxing","muay thai","thai boxing","thai kickboxing"],"group":"Combat","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":3,"trunk":3,"mass":0},"prehab":["neck","hipAbd","ankle","shoulderER","copenhagen","calf"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"all","energy":"Repeated bursts of striking and clinching over 2-3 minute rounds.","summary":"Kickboxing and Muay Thai need explosive kicks, punches and a strong clinch. The plan builds power relative to body weight, single-leg strength for kicking and neck strength for the clinch, based on wider combat-sport research.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"}],"confidence":"limited"},{"id":"bjj","name":"Brazilian jiu-jitsu","aliases":["bjj","gi","grappling","jiu jitsu","jiu-jitsu","no-gi","nogi"],"group":"Combat","q":{"maxStrength":3,"power":2,"rotational":2,"unilateral":1,"upperPull":3,"upperPush":2,"lowerBody":3,"grip":3,"neck":3,"trunk":3,"mass":0},"prehab":["neck","fingers","shoulderER","lowback","copenhagen"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Long sustained grappling efforts with repeated isometric gripping and bursts of scrambling.","summary":"Jiu-jitsu is sustained grappling where strength, grip and trunk endurance decide positions. The plan builds maximal strength relative to body weight with grip, neck and back work, as grappling success is linked to high strength.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"}],"confidence":"limited"},{"id":"judo","name":"Judo","aliases":["judoka","kodokan"],"group":"Combat","q":{"maxStrength":3,"power":3,"rotational":3,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":3,"grip":3,"neck":2,"trunk":3,"mass":0},"prehab":["neck","shoulderER","fingers","lowback","landing"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Intermittent explosive throwing attempts and grip fighting over matches of about four minutes.","summary":"Judo is explosive throwing built on strong pulling and gripping. The plan builds maximal pulling strength, power and grip relative to body weight, with neck and back work, reflecting research that higher-level grapplers are stronger and more powerful.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"}],"confidence":"moderate"},{"id":"wrestling","name":"Wrestling","aliases":["catch wrestling","collegiate wrestling","folkstyle","freestyle wrestling","greco","greco-roman"],"group":"Combat","q":{"maxStrength":3,"power":3,"rotational":2,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":3,"grip":3,"neck":3,"trunk":3,"mass":0},"prehab":["neck","shoulderER","lowback","landing","copenhagen"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Repeated high-force grappling efforts over periods of about three minutes.","summary":"Wrestling demands high strength and power under fatigue within a weight class. The plan prioritises maximal strength relative to body weight plus neck and grip work, based on research showing successful grapplers are stronger and more powerful.","evidence":[{"claim":"Across combat sports, maximal strength, power and anaerobic capacity distinguish higher-level competitors, with grapplers relying more on maximal force and strikers on fast, lighter-load power.","source":"James et al. 2016, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworkspost2013/2325"},{"claim":"In high school athletes, each 1 lb increase in neck strength was associated with 5% lower odds of concussion (an observational link, not a trial).","source":"Collins et al. 2014, Journal of Primary Prevention","url":"https://www.springermedicine.com/neck-strength-a-protective-factor-reducing-risk-for-concussion-i/21683656"}],"confidence":"moderate"},{"id":"karate","name":"Karate / taekwondo","aliases":["kata","kumite","kung fu","kyokushin","martial arts","shotokan","taekwondo","tkd","wado ryu"],"group":"Combat","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":1,"upperPush":2,"lowerBody":3,"grip":0,"neck":1,"trunk":3,"mass":0},"prehab":["landing","ankle","hipFlex","nordic","hipAbd"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Kumite is mostly aerobic (about 78%) with 1.5 s explosive actions in a 1:1.5 effort to pause pattern; kata is 1.5-3 min of continuous controlled power.","summary":"Karate is won with fast, light-load power: winners produce more power at 30% of max, not more max strength. The plan builds explosive single-leg and rotational power, kicking hip strength and repeat-effort fitness, with knee and ankle prevention.","evidence":[{"claim":"In official kumite, high-intensity actions last about 1.5 s, the effort to pause ratio is about 1:1.5, and blood lactate reaches about 11 mmol/L.","source":"Chaabene et al. 2014, Asian Journal of Sports Medicine","url":"https://brieflands.com/articles/asjsm-73549"},{"claim":"Winners of national-team kumite bouts produced about 23% more upper-limb and 11% more lower-limb power at 30% of one-rep max, with no difference in maximal strength or jump height.","source":"Roschel et al. 2009, Journal of Sports Science and Medicine","url":"https://jssm.org/jssm-08-CSSI3-20.xml-Fulltext"},{"claim":"Kumite causes about 88 injuries per 1000 athlete-exposures, mostly minor head and neck contusions.","source":"Lystad et al. 2020, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/54/16/976"}],"confidence":"moderate"},{"id":"cycling","name":"Road cycling","aliases":["bike","cycling","gravel","road bike","road racing","sportive","time trial"],"group":"Endurance","q":{"maxStrength":3,"power":2,"rotational":0,"unilateral":2,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":1,"trunk":2,"mass":0},"prehab":["lowback","hipAbd","tspine"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Long aerobic efforts with surges, climbs and sprints.","summary":"Cycling is mainly aerobic, but heavy leg strength training makes riders more economical. The plan uses heavy, low-rep leg work kept separate from hard rides, plus back endurance, without adding unnecessary upper-body mass.","evidence":[{"claim":"Adding heavy strength training to endurance training improves running and cycling economy and performance, with heavy strength work giving the clearest benefit for cyclists.","source":"Rønnestad & Mujika 2014, Scandinavian Journal of Medicine & Science in Sports","url":"https://doi.org/10.1111/sms.12104"},{"claim":"Doing endurance and strength training together does not blunt muscle growth or maximal strength, but can blunt explosive strength, especially when both are done in the same session.","source":"Schumann et al. 2022, Sports Medicine","url":"https://researchonline.jcu.edu.au/71546/"}],"confidence":"strong"},{"id":"mtb","name":"Mountain biking","aliases":["cross-country","cyclocross","dh","downhill","enduro","mountain bike","mtb","trail riding","xc"],"group":"Endurance","q":{"maxStrength":2,"power":3,"rotational":1,"unilateral":2,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","wrist","lowback","neck"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Aerobic riding with repeated short, high-power climbs and technical bursts.","summary":"Mountain biking needs leg strength and power for climbs plus upper-body and grip strength to control the bike. The plan combines heavy leg work with upper-body, grip and trunk strength, drawing on road cycling research as MTB-specific studies are limited.","evidence":[{"claim":"Adding heavy strength training to endurance training improves running and cycling economy and performance, with heavy strength work giving the clearest benefit for cyclists.","source":"Rønnestad & Mujika 2014, Scandinavian Journal of Medicine & Science in Sports","url":"https://doi.org/10.1111/sms.12104"}],"confidence":"limited"},{"id":"swimming","name":"Swimming","aliases":["distance swimming","masters swimming","open water swimming","sprint swimming","swim","triathlon swim"],"group":"Endurance","q":{"maxStrength":2,"power":2,"rotational":1,"unilateral":1,"upperPull":3,"upperPush":2,"lowerBody":2,"grip":0,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","scap","tspine","lowback","copenhagen"],"season":{"off":3,"pre":3,"in":2},"avoidBefore":"upper","energy":"From short sprint races to long aerobic sets, with high shoulder training volume.","summary":"Swimming relies on upper-body pulling power and a strong trunk, with high shoulder loads. The plan uses low-volume, high-force or fast strength work, which transfers best to swim performance, plus rotator cuff work to protect the shoulders.","evidence":[{"claim":"Low-volume, high-velocity or high-force resistance training transfers best to swimming performance and stroke length.","source":"Crowley, Harrison & Lyons 2017, Sports Medicine","url":"https://pure.ul.ie/en/publications/the-impact-of-resistance-training-on-swimming-performance-a-syste/"},{"claim":"A shoulder programme of rotator cuff external rotation strength, scapular control and mobility reduced shoulder problems by 28% in elite handball players.","source":"Andersson et al. 2017, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/51/14/1073"}],"confidence":"moderate"},{"id":"rowing","name":"Rowing","aliases":["crew","erg","indoor rowing","lightweight rowing","regatta","sculling","sweep rowing"],"group":"Endurance","q":{"maxStrength":3,"power":2,"rotational":0,"unilateral":1,"upperPull":3,"upperPush":1,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":2},"prehab":["lowback","hipAbd","wrist","tspine"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Sustained high-power aerobic efforts, about 6-8 minutes for a 2 km race.","summary":"Rowing is a powerful leg drive over a long aerobic effort. The plan builds heavy leg and pulling strength and back endurance, as leg strength is strongly linked to 2 km times and can be maintained with one or two heavy sessions a week in season.","evidence":[{"claim":"Lower-body strength and power (e.g. leg press) are moderately to strongly linked to 2,000 m ergometer times, and maximal strength can be maintained in season with one or two heavy sessions a week.","source":"Lawton, Cronin & McGuigan 2011, Sports Medicine","url":"https://ro.ecu.edu.au/ecuworks2011/104"}],"confidence":"moderate"},{"id":"kayaking","name":"Kayaking / canoeing","aliases":["canoe","canoe slalom","canoe sprint","canoeing","kayak","kayak marathon","paddling","sprint kayak","sup"],"group":"Endurance","q":{"maxStrength":2,"power":2,"rotational":3,"unilateral":1,"upperPull":3,"upperPush":2,"lowerBody":1,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","scap","wrist","lowback","tspine"],"season":{"off":3,"pre":3,"in":2},"avoidBefore":"upper","energy":"Aerobic paddling with sprint races lasting from about 30 seconds to 4 minutes.","summary":"Paddling depends on upper-body pulling strength and trunk rotation. The plan builds pulling and pressing strength with rotational trunk work and shoulder care; paddling-specific strength research is limited.","evidence":[],"confidence":"limited"},{"id":"trailrunning","name":"Trail / fell running","aliases":["fell running","mountain running","skyrunning","trail running","ultra","ultramarathon","vertical km"],"group":"Endurance","q":{"maxStrength":2,"power":2,"rotational":0,"unilateral":3,"upperPull":0,"upperPush":0,"lowerBody":3,"grip":0,"neck":0,"trunk":2,"mass":0},"prehab":["ankle","calf","patellar","shin","hipAbd"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":"lower","energy":"Long aerobic running where climbs demand hip and knee power and descents demand eccentric braking strength.","summary":"Trail running is long aerobic work with steep climbs and technical descents; downhill braking damages muscle most in runners who rarely do it. The plan builds leg strength and stiffness, eccentric quad tolerance and ankle and calf capacity, and keeps gym volume low so it does not compete with running.","evidence":[{"claim":"Uphill and downhill time-trial performance were both predicted by maximal knee extensor strength alongside aerobic speed.","source":"Lemire et al. 2021, Journal of Science and Medicine in Sport","url":"https://lab3072.unistra.fr/publications/publications-marquantes/physiological-factors-determining-downhill-vs-uphill-running-endurance-performance"},{"claim":"Downhill running causes muscle damage that cuts performance, worst in runners with little downhill experience; prior downhill exposure is the best-supported protection.","source":"Bontemps et al. 2020, Sports Medicine","url":"https://researchonline.ljmu.ac.uk/id/eprint/14430/"},{"claim":"Strength training (resistance plus plyometrics, 2-3 times a week for 8-12 weeks) produced a large improvement in running economy in highly trained distance runners.","source":"Balsalobre-Fernandez, Santos-Concejero & Grivas 2016, Journal of Strength and Conditioning Research","url":"https://pubmed.ncbi.nlm.nih.gov/26694507/"}],"confidence":"moderate"},{"id":"xcski","name":"Cross-country skiing","aliases":["biathlon","classic skiing","cross country skiing","nordic skiing","roller skiing","rollerski","skate skiing","skimo","xc skiing"],"group":"Endurance","q":{"maxStrength":3,"power":2,"rotational":1,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":3,"grip":1,"neck":0,"trunk":3,"mass":1},"prehab":["lowback","shoulderER","hipAbd","ankle","copenhagen"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"all","energy":"Very high aerobic demand (world-class VO2max, maximal oxygen uptake, above 80 ml/kg/min for men, about 70 for women) using the whole body, with hard surges on climbs and in sprint heats.","summary":"Cross-country skiing is whole-body endurance where poling power and leg drive both matter, and the lower back is the most injured area. The plan uses heavy upper-body pulling and leg strength to improve poling economy, plus back, shoulder and lateral hip work.","evidence":[{"claim":"Nine weeks of heavy upper-body strength training improved double-poling economy and time to exhaustion in cross-country skiers.","source":"Osteras, Helgerud & Hoff 2002, European Journal of Applied Physiology","url":"https://lida.sport-iat.de/ta/Record/4007707"},{"claim":"World-class skiers train about 860 h a year, with about 6% as strength training; skiing and roller skiing make up 68% of endurance time.","source":"Walther et al. 2023, Frontiers in Physiology","url":"https://www.frontiersin.org/journals/physiology/articles/10.3389/fphys.2023.1288606/full"},{"claim":"Cross-country skiing has the lowest injury rate of the World Cup ski disciplines, 6.3 time-loss injuries per 100 athletes a season.","source":"Florenes et al. 2012, Scandinavian Journal of Medicine and Science in Sports","url":"https://lida.sport-iat.de/svd/Record/4023959"}],"confidence":"moderate"},{"id":"climbing","name":"Rock climbing & bouldering","aliases":["bouldering","climbing","indoor climbing","lead climbing","rock climbing","sport climbing","top rope","trad","trad climbing"],"group":"Climbing & board","q":{"maxStrength":2,"power":2,"rotational":1,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":1,"grip":3,"neck":0,"trunk":3,"mass":0},"prehab":["fingers","shoulderER","wrist","scap"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"upper","energy":"Repeated high-intensity grip efforts; short powerful moves in bouldering, longer sustained efforts on routes.","summary":"Climbing is limited by finger strength and pulling strength relative to body weight. The plan uses hangboard and pulling work, which improves finger strength, plus antagonist pushing and shoulder work to keep the joints balanced.","evidence":[{"claim":"Eight weeks of weighted hangboard training improved grip and finger strength in intermediate to advanced climbers compared with climbing alone.","source":"Mundry et al. 2021, Scientific Reports","url":"https://doi.org/10.1038/s41598-021-92898-2"}],"confidence":"moderate"},{"id":"skateboarding","name":"Skateboarding","aliases":["bowl","park skating","skate","skateboard","skatepark","street skating","vert"],"group":"Climbing & board","q":{"maxStrength":1,"power":3,"rotational":2,"unilateral":3,"upperPull":0,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":2,"mass":1},"prehab":["ankle","wrist","landing","calf","patellar"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":"lower","energy":"Long sessions of short explosive pushes, pops and landings with walking and rest between; heart rate averages about 72% of max.","summary":"Skateboarding is repeated jumping and hard landings, and most injuries are wrist and forearm fractures from falls, then ankle injuries. The plan builds leg power and landing control, ankle and calf capacity, and wrist and upper-body strength to take falls.","evidence":[{"claim":"In 5026 hospital presentations, 56% of injuries were to the upper limb (mostly hand and wrist), 44% were fractures, and ankle injuries made up about 45% of lower-limb injuries.","source":"Quinn et al. 2024, Cureus","url":"https://assets.cureus.com/uploads/original_article/pdf/229446/20240306-17519-stj7rh.pdf"},{"claim":"Skateboarding had 21 injuries per 100 athletes at the Tokyo 2020 Olympics, more than double the Games average.","source":"Soligard et al. 2023, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/57/1/46"},{"claim":"In a randomised trial in 5029 snowboarders, wrist guards cut wrist injuries from 29 to 8.","source":"Ronning et al. 2001, American Journal of Sports Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/11573916/"}],"confidence":"limited"},{"id":"alpineskiing","name":"Alpine skiing","aliases":["downhill","downhill skiing","giant slalom","ski racing","ski touring","skiing","slalom","super-G"],"group":"Snow & water","q":{"maxStrength":3,"power":2,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":3,"mass":2},"prehab":["landing","hipAbd","nordic","lowback","copenhagen"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated runs of 1-2 minutes with high, sustained leg loads, often eccentric.","summary":"Skiing puts high, sustained loads through the legs, especially when absorbing turns. The plan builds heavy leg strength and eccentric control with knee-protective landing work; skiing-specific trials are limited, so this draws on wider ACL research.","evidence":[{"claim":"Neuromuscular injury-prevention programmes cut ACL injuries by about 50% overall and non-contact ACL injuries in female athletes by about 67%.","source":"Webster & Hewett 2018, Journal of Orthopaedic Research","url":"https://lida.sport-iat.de/ta/Record/4054906"},{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"}],"confidence":"limited"},{"id":"snowboarding","name":"Snowboarding","aliases":["big air","boardercross","boarding","freeride","freestyle snowboarding","halfpipe","slopestyle","snowboard","snowboard cross"],"group":"Snow & water","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":2,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":3,"mass":1},"prehab":["landing","wrist","ankle","tspine"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Repeated runs with sustained squatting and occasional jumps and falls.","summary":"Snowboarding needs strong legs for sustained edging and good landing control. The plan builds leg strength, trunk stability and landing technique, plus wrist strength for falls; snowboard-specific research is limited.","evidence":[],"confidence":"limited"},{"id":"surfing","name":"Surfing","aliases":["bodyboarding","competitive surfing","longboard","shortboard","surf"],"group":"Snow & water","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":2,"upperPull":3,"upperPush":2,"lowerBody":2,"grip":0,"neck":0,"trunk":3,"mass":1},"prehab":["shoulderER","scap","tspine","lowback","landing"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"upper","energy":"Long periods of paddling punctuated by explosive pop-ups and short rides.","summary":"Surfing is mostly paddling, with explosive pop-ups and short rides. The plan builds upper-body pulling endurance and trunk strength with shoulder care and leg power for the pop-up; surfing-specific strength research is limited.","evidence":[],"confidence":"limited"},{"id":"sailing","name":"Sailing","aliases":["470","49er","America's Cup","dinghy sailing","grinder","ILCA","keelboat","kitesurfing","Laser","windsurfing","yachting"],"group":"Snow & water","q":{"maxStrength":2,"power":1,"rotational":1,"unilateral":1,"upperPull":3,"upperPush":1,"lowerBody":2,"grip":3,"neck":0,"trunk":3,"mass":1},"prehab":["lowback","shoulderER","wrist","patellar"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":null,"energy":"Long periods of sustained isometric holding (hiking) with bursts of pulling.","summary":"Dinghy sailing involves long isometric hiking holds and repeated rope pulling. The plan builds back, trunk and pulling endurance and grip strength; sailing-specific research is limited.","evidence":[],"confidence":"limited"},{"id":"sprinting","name":"Sprinting (track)","aliases":["100m","100m hurdles","110m hurdles","200m","400m","400m hurdles","60m","hurdles","sprint","sprinter"],"group":"Athletics","q":{"maxStrength":3,"power":3,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":2,"mass":1},"prehab":["nordic","calf","copenhagen","hipAbd"],"season":{"off":3,"pre":3,"in":2},"avoidBefore":"lower","energy":"Maximal efforts of under a minute that rely on speed and power.","summary":"Sprinting is about producing large forces very quickly. The plan builds heavy leg strength and power, since squat strength gains carry over to sprint times, and includes Nordic hamstring work to protect against the commonest sprint injury.","evidence":[{"claim":"Gains in lower-body (squat) strength transfer to sprint performance, with strength gains strongly correlated with sprint improvements.","source":"Seitz et al. 2014, Sports Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/25059334/"},{"claim":"Injury-prevention programmes that include the Nordic hamstring exercise reduce hamstring injuries by up to 51%.","source":"van Dyk, Behan & Whiteley 2019, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/53/21/1362"}],"confidence":"strong"},{"id":"jumps","name":"Jumping events","aliases":["high jump","horizontal jumps","jumper","long jump","pole vault","triple jump","vertical jumps"],"group":"Athletics","q":{"maxStrength":3,"power":3,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":2,"mass":1},"prehab":["landing","calf","nordic","patellar","ankle"],"season":{"off":3,"pre":3,"in":2},"avoidBefore":"lower","energy":"Maximal single explosive efforts with full recovery between attempts.","summary":"Jumping events depend on explosive leg power and stiff, strong tendons. The plan uses heavy strength and power work for the legs with calf and landing work; event-specific trials are limited, so this draws on wider strength and sprint research.","evidence":[{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"},{"claim":"Gains in lower-body (squat) strength transfer to sprint performance, with strength gains strongly correlated with sprint improvements.","source":"Seitz et al. 2014, Sports Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/25059334/"}],"confidence":"limited"},{"id":"throws","name":"Throwing events","aliases":["discus","hammer","hammer throw","javelin","shot","shot put","weight throw"],"group":"Athletics","q":{"maxStrength":3,"power":3,"rotational":3,"unilateral":2,"upperPull":2,"upperPush":3,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":2},"prehab":["shoulderER","lowback","scap","tspine"],"season":{"off":3,"pre":3,"in":2},"avoidBefore":"all","energy":"Single maximal explosive efforts with full recovery between attempts.","summary":"Throwing events need maximal strength and rotational power, and extra muscle mass helps. The plan prioritises heavy lifting and power with shoulder care, based on strength research as throws-specific trials are limited.","evidence":[{"claim":"Greater muscular strength is linked to better jumping, sprinting, change of direction and sport-specific performance, and may lower injury risk.","source":"Suchomel, Nimphius & Stone 2016, Sports Medicine","url":"https://doi.org/10.1007/s40279-016-0486-0"}],"confidence":"limited"},{"id":"golf","name":"Golf","aliases":["golfer","golfing","pitch and putt"],"group":"Other","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":2,"upperPull":1,"upperPush":1,"lowerBody":2,"grip":2,"neck":0,"trunk":3,"mass":1},"prehab":["lowback","hipRot","tspine","shoulderER","wrist"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":null,"energy":"Low physical intensity overall with repeated maximal swings over several hours of walking.","summary":"Golf is a series of fast, rotational swings over a long walk. The plan builds leg and trunk power and grip strength, which are linked to clubhead speed and driving distance, plus back and shoulder care.","evidence":[{"claim":"Driving distance and clubhead speed relate to muscle strength, with leg-hip power, trunk power and grip strength most relevant; combined strength programmes often improve swing speed.","source":"Torres-Ronda, Sánchez-Medina & González-Badillo 2011, Journal of Sports Science and Medicine","url":"https://www.jssm.org/jssm-10-9.xml-Fulltext"}],"confidence":"moderate"},{"id":"gymnastics","name":"Gymnastics","aliases":["acrobatic gymnastics","artistic gymnastics","calisthenics","trampoline","trampolining","tumbling"],"group":"Other","q":{"maxStrength":3,"power":3,"rotational":1,"unilateral":2,"upperPull":3,"upperPush":3,"lowerBody":3,"grip":3,"neck":0,"trunk":3,"mass":0},"prehab":["wrist","landing","ankle","shoulderER","lowback","calf"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Short, maximal efforts of strength, power and control lasting seconds to about 90 seconds.","summary":"Gymnastics demands high strength relative to body weight, explosive power and resilient wrists and shoulders. The plan focuses on relative strength, landing control and wrist and shoulder care; gym-based research in gymnasts is limited.","evidence":[],"confidence":"limited"},{"id":"dance","name":"Dance","aliases":["ballet","commercial dance","contemporary","contemporary dance","jazz dance","modern dance"],"group":"Other","q":{"maxStrength":2,"power":2,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":3,"mass":0},"prehab":["calf","ankle","landing","hipAbd","hipRot"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"lower","energy":"Intermittent bursts of jumping and movement during long rehearsals and performances.","summary":"Dance needs strong, controlled legs and ankles for jumps and landings without adding bulk. The plan focuses on single-leg strength, calf and ankle work and landing control; dance-specific strength research is limited.","evidence":[{"claim":"Proprioceptive (balance) training reduced ankle sprain rates by about 35%, with the clearest effect in people who had sprained an ankle before.","source":"Schiftan, Ross & Hahne 2015, Journal of Science and Medicine in Sport","url":"https://pubmed.ncbi.nlm.nih.gov/24831756/"}],"confidence":"limited"},{"id":"horseriding","name":"Horse riding","aliases":["cross-country riding","dressage","equestrian","eventing","jockey","riding","show jumping"],"group":"Other","q":{"maxStrength":1,"power":1,"rotational":1,"unilateral":2,"upperPull":2,"upperPush":1,"lowerBody":2,"grip":1,"neck":1,"trunk":3,"mass":0},"prehab":["lowback","copenhagen","hipAbd","hipRot","tspine"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":null,"energy":"Sustained postural work with moderate aerobic demands, higher in eventing and racing.","summary":"Riding relies on trunk control, leg strength and back endurance to stay balanced in the saddle. The plan focuses on trunk, back and hip strength; riding-specific strength research is limited.","evidence":[],"confidence":"limited"},{"id":"esports","name":"Esports","aliases":["competitive gaming","e-sports","gaming","pro gaming","video gaming"],"group":"Other","q":{"maxStrength":1,"power":0,"rotational":0,"unilateral":1,"upperPull":2,"upperPush":1,"lowerBody":1,"grip":1,"neck":1,"trunk":2,"mass":0},"prehab":["wrist","tspine","shoulderER","neck"],"season":{"off":3,"pre":3,"in":2},"energy":"Hours of seated play with low energy demand; fitness supports health, posture and focus rather than in-game energy.","summary":"Esports means long seated sessions with heavy hand and wrist use, and neck, back and wrist pain are common. The gym will not make you better at the game directly, but full-body strength, posture work and activity breaks protect your health and support focus.","evidence":[{"claim":"In collegiate esports players, eye fatigue (56%), neck and back pain (42%) and wrist pain (36%) were common, and 40% did no physical activity.","source":"DiFrancisco-Donoghue et al. 2019, BMJ Open Sport and Exercise Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/30792883/"},{"claim":"A 6 min walk during 2 h of play improved executive function compared with a seated rest, without affecting in-game performance.","source":"DiFrancisco-Donoghue et al. 2021, BMJ Open Sport and Exercise Medicine","url":"https://bmjopensem.bmj.com/content/7/3/e001118"}],"confidence":"limited"},{"id":"middledistance","name":"Middle distance (800 m, 1500 m)","aliases":["1500 m","1500m","800 m","800m","middle-distance running","mile","miler","track running"],"group":"Athletics","q":{"maxStrength":2,"power":2,"rotational":0,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":2,"mass":0},"prehab":["calf","nordic","hipAbd","ankle","shin"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":"lower","energy":"800 m is about two-thirds aerobic and 1500 m about 80-85% aerobic, and both need a big gap between top speed and VO2max (maximal aerobic) speed.","summary":"Middle distance needs a big aerobic engine, top-end speed, and calves, tendons and bones that cope with high mileage. The plan uses heavy and explosive lifting twice a week to improve running economy without adding bulk, plus calf, hamstring and shin protection.","evidence":[{"claim":"Heavy and explosive strength training improves running economy and middle- and long-distance performance without harming endurance.","source":"Blagrove, Howatson & Hayes 2018, Sports Medicine","url":"https://repository.lboro.ac.uk/articles/journal_contribution/Effects_of_strength_training_on_the_physiological_determinants_of_middle-_and_long-distance_running_performance_a_systematic_review/9619553"},{"claim":"World-class distance runners do about 80% of their running at low intensity, with structured threshold and VO2max sessions.","source":"Haugen et al. 2022, Sports Medicine Open","url":"https://munin.uit.no/handle/10037/26245"}],"confidence":"moderate"},{"id":"motorsport","name":"Motorsport","aliases":["F1","Formula 1","GT racing","karting","racing","racing driver","rally","saloon car racing","single-seater"],"group":"Endurance","q":{"maxStrength":2,"power":1,"rotational":1,"unilateral":1,"upperPull":2,"upperPush":2,"lowerBody":2,"grip":2,"neck":3,"trunk":3,"mass":0},"prehab":["neck","shoulderER","wrist","lowback"],"season":{"off":3,"pre":3,"in":2},"avoidBefore":"all","energy":"Long periods at high heart rate under heat and g-force, so drivers need a strong aerobic base plus neck and trunk endurance.","summary":"Racing loads the neck, trunk and forearms for the whole race, while heat and high heart rates wear down concentration. The plan builds neck strength and endurance, grip and an aerobic base, and keeps hard sessions away from race weekends.","evidence":[{"claim":"Neck strength is the main sport-specific adaptation in Formula 1 drivers, who race at high heart rates under heat stress.","source":"Tyler et al. 2026, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/60/9/649"},{"claim":"Open-wheel racing produces about 4-5 g in braking and cornering, with upper-body and neck fatigue a prominent response.","source":"Review of physiological responses to open-wheeled racing 2021, Edith Cowan University","url":"https://lida.sport-iat.de/ta/Record/4068839?lng=en"}],"confidence":"limited"},{"id":"trackcycling","name":"Track cycling","aliases":["flying 200","keirin","kilo","madison","omnium","pursuit","team sprint","track cycling","track sprint","velodrome"],"group":"Endurance","q":{"maxStrength":3,"power":3,"rotational":0,"unilateral":2,"upperPull":2,"upperPush":1,"lowerBody":3,"grip":2,"neck":0,"trunk":3,"mass":2},"prehab":["nordic","lowback","hipAbd","copenhagen"],"season":{"off":3,"pre":3,"in":2},"avoidBefore":"lower","energy":"Alactic and glycolytic: maximal efforts of about 10 s to 70 s at very high power.","summary":"Track sprinting needs huge leg force for standing starts and very high cadence for flying efforts. The gym is a main training tool: heavy squats and hinges, Olympic lifts and jumps, with Nordics all year.","evidence":[{"claim":"Sprint cycling power depends on maximal force and speed; heavy strength and leg extensor size support it, alongside on-bike torque and speed work.","source":"Douglas, Ross and Martin 2021, Sports Medicine Open","url":"https://sportsmedicine-open.springeropen.com/articles/10.1186/s40798-021-00341-7"},{"claim":"Heavy strength training added to cycling training improves sprint power and cycling performance.","source":"Rønnestad and Mujika 2014, Scandinavian Journal of Medicine and Science in Sports","url":"https://doi.org/10.1111/sms.12104"}],"confidence":"moderate"},{"id":"archery","name":"Archery","aliases":["recurve","compound bow","barebow","target archery","field archery","3D archery","bow shooting"],"group":"Other","q":{"maxStrength":1,"power":0,"rotational":1,"unilateral":1,"upperPull":3,"upperPush":2,"lowerBody":1,"grip":2,"neck":0,"trunk":2,"mass":0},"prehab":["shoulderER","scap","tspine","elbow","lowback"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"upper","energy":"Low energy demand: dozens of short static holds over a long day, so shoulder girdle endurance and an easy aerobic base matter more than fitness for sprinting.","summary":"Archery asks the shoulders to hold a heavy draw steady, shot after shot, and shoulder pain is very common. The plan builds rotator cuff and scapular endurance on both sides, a stable trunk and stance, and grows arrow volume gradually.","evidence":[{"claim":"In 156 competitive archers, 54% had shoulder pain at the time of the survey and 83% had had it at some point; past shoulder pain was the main linked factor.","source":"Grover & Sinha 2017, Asian Journal of Sports Medicine","url":"https://brieflands.com/articles/asjsm-13338"},{"claim":"Archers who train only one side showed more rotation, mainly internal rotation, on the pull-arm shoulder than archers who train both sides; the authors suggest bilateral training to limit this.","source":"Schmitt, Vogt, Wilke & Niederer 2021, BMC Sports Science, Medicine and Rehabilitation","url":"https://doaj.org/article/49de7c94863d4e259a63b45f564cbbf9"},{"claim":"In US emergency department data, about two thirds of archery injuries in men were to the fingers, mostly cuts, pointing to technique and equipment as the main fixes for acute injury.","source":"Konda et al. 2023, Orthopedic Reviews","url":"https://orthopedicreviews.openmedicalpublishing.org/article/88933-archery-related-musculoskeletal-injuries-an-epidemiological-study-revealing-injury-sites-risk-factors-and-implications-for-prevention"}],"confidence":"limited"},{"id":"bmx","name":"BMX","aliases":["bmx racing","bmx freestyle","bmx park","bmx dirt","bmx street","flatland","supercross bmx","bicycle motocross"],"group":"Endurance","q":{"maxStrength":3,"power":3,"rotational":1,"unilateral":2,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":2,"neck":1,"trunk":3,"mass":1},"prehab":["shoulderER","wrist","neck","lowback","landing"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"lower","energy":"A race lap lasts about 35-45 s: peak power comes in the first 2 s out of the gate, the rest is pumping and jumping, so it is ATP-PC and glycolytic with an aerobic base for repeat motos.","summary":"BMX racing is decided by gate-start power and the strength to pump and absorb jumps; freestyle adds big landings and crashes. The plan builds heavy leg strength and power, upper-body and trunk strength for bike control, and shoulder, wrist and neck resilience for falls.","evidence":[{"claim":"Elite riders finish a race in about 40 s and spend only about a third of it pedalling; the rest is pumping and jumping, so BMX is a strength and power sport.","source":"Cowell, Cronin & McGuigan 2011, Journal of Sports Science and Medicine","url":"https://jssm.org/jssm-10-420.xml-Fulltext","grade":"moderate"},{"claim":"In a systematic review, maximal strength (r = 0.84) and peak sprint power (r = 0.87) were strongly linked to BMX race performance, and jump height to race time.","source":"Becerra-Patino et al. 2025, Journal of Functional Morphology and Kinesiology","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12194740/","grade":"moderate"},{"claim":"Contusions, lacerations and fractures are the most common BMX injuries; injury rates reached 37.5 per 100 athletes at the 2016 Olympics, and prevention strategies are barely tested.","source":"Scoping review 2025, Sports Health","url":"https://lida.sport-iat.de/ta/Record/4090502?lng=de","grade":"moderate"}],"confidence":"limited"},{"id":"diving","name":"Diving","aliases":["springboard diving","platform diving","high diving","cliff diving","synchronised diving","3m springboard","10m platform"],"group":"Snow & water","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":1,"upperPull":2,"upperPush":2,"lowerBody":3,"grip":1,"neck":1,"trunk":3,"mass":0},"prehab":["lowback","shoulderER","wrist","scap","patellar"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"all","energy":"Each dive is a single maximal take-off and a flight of 1-3 s, so it is almost all ATP-PC; the aerobic demand is low, but sessions hold many repeats.","summary":"Diving needs a powerful take-off, fast rotation from a stiff, strong trunk, and wrists, shoulders and lower back that tolerate hundreds of water entries. The plan builds jump power and leg strength, anti-extension trunk strength, and shoulder, wrist and back resilience, kept short around pool work.","evidence":[{"claim":"A systematic review of 28 studies found the shoulder, lower back, trunk and wrist are the most injured areas in divers; low back pain is reported by up to 89% over a career.","source":"Currie et al. 2025, Sports Health","url":"https://researchsystem.canberra.edu.au/ws/portalfiles/portal/113004481/currie-et-al-2024-diving-into-the-health-problems-of-competitive-divers-a-systematic-review-of-injuries-and-illnesses.pdf","grade":"moderate"},{"claim":"Water entry was the mechanism in about 71% of reported injuries; platform divers mostly hurt the upper limb and springboard divers the lower limb.","source":"Currie et al. 2025, Sports Health","url":"https://researchsystem.canberra.edu.au/ws/portalfiles/portal/113004481/currie-et-al-2024-diving-into-the-health-problems-of-competitive-divers-a-systematic-review-of-injuries-and-illnesses.pdf","grade":"moderate"},{"claim":"Back and reverse dives, and platform more than springboard, are linked to more injuries; the wrist, shoulder and lumbar spine are injured most.","source":"Rubin 1999, Clinics in Sports Medicine","url":"https://lida.sport-iat.de/ta/Record/4002912?lng=en","grade":"practice"}],"confidence":"limited"},{"id":"fencing","name":"Fencing","aliases":["fencing","foil","epee","épée","sabre","saber","olympic fencing","swordfighting"],"group":"Combat","q":{"maxStrength":2,"power":3,"rotational":1,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":1,"neck":0,"trunk":2,"mass":0},"prehab":["ankle","nordic","copenhagen","patellar","lowback"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"lower","energy":"Short explosive lunges and footwork bursts (about 2.5 s per point in sabre, 5 s in foil, 15 s in épée) on an aerobic base that has to last a long tournament day.","summary":"Fencing is repeated lunging and fast changes of direction from an asymmetric stance, and most injuries are ankle sprains and lower-limb strains. The plan builds horizontal leg power and single-leg strength on both sides, strong hamstrings and adductors, and ankle control.","evidence":[{"claim":"In FIE competitions 72% of time-loss injuries were lower limb, ankle sprain was the most common single injury (25%), and épée had about half the injury risk of foil and sabre.","source":"Harmer 2019, Br J Sports Med","url":"https://bjsm.bmj.com/content/53/7/442"},{"claim":"Standing broad jump was the strongest predictor of lunge velocity and change-of-direction speed in fencers, and single-leg jumps were 9% stronger on the front leg.","source":"Turner et al. 2016, J Strength Cond Res","url":"https://bibgraph.hpcr.jp/abst/pubmed/26808849"},{"claim":"Work:rest differs by weapon: about 1:1 to 2:1 in épée, 1:1 to 1:3 in foil and 1:5 to 1:6 in sabre.","source":"Oates, Price & Bottoms 2023, J Elite Sport Perform","url":"https://uhra.herts.ac.uk/id/eprint/10363/2/73815-physiological-demands-of-fencing-a-narrative-review.pdf"}],"confidence":"moderate"},{"id":"figureskating","name":"Figure skating","aliases":["figure skating","ice skating","skating","singles skating","pairs skating","ice dance","ice dancing","synchronised skating","synchro"],"group":"Other","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":0,"trunk":3,"mass":0},"prehab":["ankle","landing","patellar","lowback","hipAbd"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"lower","energy":"A free skate of about 4 min is roughly three quarters aerobic, with the rest from short explosive jumps, spins and footwork.","summary":"Figure skating needs explosive take-offs, fast rotation and single-leg landings of up to 9 times body weight, and the knee, ankle and foot carry most injuries. The plan builds leg power and landing capacity, a stiff rotating trunk, tendon and ankle robustness, and keeps energy intake high enough to protect bone.","evidence":[{"claim":"Ankle sprain is the most common injury, patellar tendinopathy the most common overuse injury, and stress fractures the most common overuse injury in female singles; pairs accounts for most upper-limb injuries.","source":"Han, Geminiani & Micheli 2018, Sports Health","url":"https://lida.sport-iat.de/ta/Record/4051402?lng=en"},{"claim":"Jump landing impact rises with extra revolutions, from about 3 to 9 times body weight.","source":"Lockwood, Baudin & Gervais, citing Lockwood & Gervais 1995","url":"https://ojs.ub.uni-konstanz.de/cpa/article/view/2984/2829"},{"claim":"Free skating was estimated at about 74% aerobic, 12% anaerobic lactic and 14% anaerobic alactic, with peak heart rate about 194 bpm and lactate about 9.7 mmol/L.","source":"ECSS 2012 congress abstract, energetic demand profile in figure skating","url":"https://lida.sport-iat.de/ta/Record/4029741?lng=en"}],"confidence":"limited"},{"id":"orienteering","name":"Orienteering","aliases":["foot orienteering","sprint orienteering","forest orienteering","urban orienteering","rogaining","adventure racing","mountain marathon","trail-o"],"group":"Endurance","q":{"maxStrength":1,"power":1,"rotational":0,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":2,"grip":0,"neck":0,"trunk":2,"mass":0},"prehab":["ankle","calf","shin","hipAbd","landing"],"season":{"off":2,"pre":2,"in":1},"avoidBefore":"lower","energy":"Aerobic running on rough ground: elite orienteers hold a mean heart rate of about 167-172 beats a minute in races of 12-100 min, and forest terrain raises the oxygen cost of running by about 26%.","summary":"Orienteering is endurance running over uneven ground while navigating, so ankles, calves and shins take the punishment. The plan uses short, focused strength sessions for single-leg control, calf and ankle capacity, alongside the running that drives the fitness.","evidence":[{"claim":"In a one-year study of elite orienteers, ankle sprains were 37% of acute injuries, and overuse injuries (shin pain, Achilles, peroneal and IT band) were all in the legs.","source":"Linde 1986, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/20/3/125","grade":"moderate"},{"claim":"In elite orienteers who did a 10 min calf, balance and hop programme at least twice a week, the odds of substantial injury were about 75% lower (per-protocol; not significant on intention to treat).","source":"Halvarsson & von Rosen 2019, Physical Therapy in Sport","url":"https://search.pedro.org.au/search-results/record-detail/58730","grade":"moderate"},{"claim":"Running in forest terrain costs about 26% more oxygen than road running, and rough terrain drives ankle injuries.","source":"Creagh & Reilly 1997, Sports Medicine","url":"https://lida.sport-iat.de/twm/Record/4004305","grade":"moderate"}],"confidence":"moderate"},{"id":"parkour","name":"Parkour","aliases":["freerunning","free running","art du deplacement","traceur","parkour speed run","parkour freestyle","tricking"],"group":"Other","q":{"maxStrength":2,"power":3,"rotational":1,"unilateral":3,"upperPull":3,"upperPush":2,"lowerBody":3,"grip":3,"neck":0,"trunk":3,"mass":0},"prehab":["landing","ankle","wrist","patellar","calf"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"lower","energy":"Short maximal efforts of jumps, vaults and climbs (ATP-PC), linked into runs of 20-60 s that also tax the glycolytic system; long sessions rest on an aerobic base.","summary":"Parkour demands explosive jumping, high landing forces, a strong grip and pull for climb-ups, and ankles and wrists that tolerate repeated impacts. The plan builds leg strength and jump power, landing control on both legs, pulling and grip strength, and ankle and wrist resilience.","evidence":[{"claim":"In 180 traceurs, ankle injuries (mostly sprains) were the most common at 2.3 per 1,000 h; those who did no physical conditioning had more ankle and knee injuries.","source":"Grospretre & El Khattabi 2022, Movement and Sport Sciences","url":"https://www.mov-sport-sciences.org/articles/sm/full_html/2022/01/sm210045/sm210045.html","grade":"moderate"},{"claim":"Parkour precision and roll landings cut peak landing force by about 38-43% and loading rate by about 54-63% compared with a traditional drop landing.","source":"Puddle & Maulder 2013, Journal of Sports Science and Medicine","url":"https://www.jssm.org/jssm-12-122.xml-Fulltext","grade":"moderate"},{"claim":"In 161 practitioners, 70% reported an injury in a year; the ankle (28.5%), knee (18.4%) and wrist (12.6%) were most affected, often on precision jumps.","source":"Giner Gran 2020, SPORT TK","url":"https://revistas.um.es/sportk/article/download/412551/278711","grade":"moderate"}],"confidence":"limited"},{"id":"polo","name":"Polo","aliases":["horse polo","field polo","arena polo","snow polo","low goal polo"],"group":"Team field","q":{"maxStrength":2,"power":1,"rotational":3,"unilateral":1,"upperPull":2,"upperPush":1,"lowerBody":2,"grip":2,"neck":1,"trunk":3,"mass":1},"prehab":["lowback","copenhagen","wrist","shoulderER","neck","trunkLat"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"lower","energy":"Repeated hard efforts in 7-minute chukkas with short breaks: elite riders average about 150 bpm in a match, so an aerobic base with repeat-effort fitness matters.","summary":"Polo needs a strong trunk, adductors and legs to stay in the saddle while riding off and swinging, and injuries are rare but often serious, mostly from falls. The plan builds rotation, trunk and groin capacity, hitting-arm forearm and shoulder strength, and neck strength.","evidence":[{"claim":"In 103 polo riders, 40% were injured over two years and two thirds of injuries kept them out for more than 30 days; falls from the horse caused 44%, and the wrist and low back were the most common overuse pain sites.","source":"Neumayr & Schmitt 2019, German Journal of Sports Medicine","url":"https://www.germanjournalsportsmedicine.com/archive/archiv-2019/issue-2/injuries-in-polo-a-retrospective-evaluation-of-103-polo-riders/"},{"claim":"In Argentine high goal polo, injuries occurred at 7.8 per 1,000 player-game hours, with arms, legs and head most affected and fractures from falls the most common type.","source":"Costa-Paz, Aponte-Tinao & Muscolo 1999, British Journal of Sports Medicine","url":"https://bjsm.bmj.com/content/33/5/329"},{"claim":"Elite polo players averaged 150 bpm across a match and spent most playing time in the hard heart rate zone.","source":"Wright & Peters 2008, International Journal of Performance Analysis in Sport","url":"https://pureportal.coventry.ac.uk/en/publications/a-heart-rate-analysis-of-the-cardiovascular-demands-of-elite-leve/"}],"confidence":"limited"},{"id":"shooting","name":"Shooting","aliases":["target shooting","rifle shooting","air rifle","smallbore","fullbore","pistol shooting","air pistol","clay shooting","clay pigeon","trap","skeet","sporting clays","shotgun"],"group":"Other","q":{"maxStrength":1,"power":0,"rotational":1,"unilateral":1,"upperPull":1,"upperPush":1,"lowerBody":1,"grip":1,"neck":1,"trunk":3,"mass":0},"prehab":["lowback","trunkLat","shoulderER","scap","wrist","tspine"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"upper","energy":"Very low energy demand: long static holds and repeated gun mounts over a long day, so trunk and shoulder endurance and an easy aerobic base matter most.","summary":"Shooting rewards a still hold and clean trigger, and rifle shooters very often get low back pain from the twisted standing position. The plan builds trunk and back endurance, shoulder endurance for the hold or mount, and balance, while keeping fatigue away from competition days.","evidence":[{"claim":"In elite air rifle shooters, hold stability, aiming accuracy and the timing and cleanness of triggering explained 81% of score variation, and postural balance affected score directly and through a steadier hold.","source":"Ihalainen 2018, University of Jyväskylä doctoral thesis","url":"https://jyx.jyu.fi/jyx/Record/jyx_123456789_58545"},{"claim":"89% of 114 college rifle athletes reported low back pain linked to shooting, and 24% of them missed training or competition because of it.","source":"Urbach et al. 2025, International Journal of Sports Physical Therapy","url":"https://ijspt.scholasticahq.com/article/127385-high-prevalence-of-low-back-pain-in-college-rifle-athletes"},{"claim":"Across 19 studies, acute injuries in shooting were rare, but rifle shooters mostly reported low back problems, pistol shooters wrist and hand, and shotgun shooters shoulder problems from recoil.","source":"Harr et al. 2021, International Journal of Sports Physical Therapy","url":"https://ijspt.scholasticahq.com/article/28231-prevalence-and-incidence-of-injury-during-olympic-style-shooting-events-a-systematic-review"}],"confidence":"limited"},{"id":"skimo","name":"Ski mountaineering","aliases":["skimo","ski touring","ski mountaineering racing","splitboarding","splitboard","backcountry skiing","randonnee","vertical race"],"group":"Snow & water","q":{"maxStrength":2,"power":1,"rotational":0,"unilateral":3,"upperPull":2,"upperPush":1,"lowerBody":3,"grip":1,"neck":0,"trunk":2,"mass":0},"prehab":["landing","calf","hipAbd","lowback"],"season":{"off":3,"pre":2,"in":1},"avoidBefore":"lower","energy":"Mostly aerobic: races run at an average of about 87-93% of max heart rate for 20 min to 2 h or more, with short anaerobic surges in sprints and transitions and an eccentric leg load on the descents.","summary":"Ski mountaineering is a high-volume uphill endurance sport with a downhill that hammers the knees and thighs. The plan uses heavy, low-rep single-leg and hinge strength to make climbing cheaper and descents safer, with calf, hip and back work, while most of the fitness comes from climbing.","evidence":[{"claim":"Elite male ski mountaineers averaged a VO2max of 71 ml/kg/min against 62.5 in sub-elite; individual races average 93% of max heart rate and even downhills about 85%.","source":"Bortolan et al. 2021, Frontiers in Physiology","url":"https://www.frontiersin.org/articles/10.3389/fphys.2021.737249/full","grade":"moderate"},{"claim":"In a survey of 104 ski mountaineers, most injuries were in the lower body and the knee was the most common site (29.6%); injured skiers did fewer core sessions and more ski sessions a week.","source":"Etayo-Urtasun et al. 2022, Sports","url":"https://doaj.org/article/ea312ccea325459a9d04f6a10e2dd758","grade":"moderate"},{"claim":"Heavy strength training added to endurance training improves running and cycling economy and performance.","source":"Ronnestad & Mujika 2014, Scandinavian Journal of Medicine and Science in Sports","url":"https://www.inigomujika.com/en/2013/08/13/optimizing-strength-training-for-running-and-cycling-endurance-performance-a-review-2/3040/","grade":"strong"}],"confidence":"limited"},{"id":"speedskating","name":"Speed skating","aliases":["speed skating","speedskating","long track","short track","inline skating","inline speed skating","roller speed skating","ice racing"],"group":"Endurance","q":{"maxStrength":3,"power":3,"rotational":0,"unilateral":3,"upperPull":1,"upperPush":0,"lowerBody":3,"grip":0,"neck":1,"trunk":2,"mass":1},"prehab":["lowback","copenhagen","patellar","hipAbd","tspine"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"lower","energy":"From mostly anaerobic in the 500 m to mostly aerobic over 5,000 to 10,000 m, all in a deep crouch that restricts blood flow to the thighs.","summary":"Speed skating is repeated sideways leg pushes from a deep crouch, and back pain, knee overuse and falls are the main problems. The plan builds deep-knee leg strength and lateral power, adductor and hip strength, a robust lower and upper back, and an aerobic base mainly on the bike.","evidence":[{"claim":"Seasonal back pain prevalence reaches up to 84% in long and short track skaters, and no study has yet tested whether any prevention measure works.","source":"Hendricks, Verhagen & van de Water 2024, Scand J Med Sci Sports","url":"https://www.citedrive.com/en/discovery/epidemiology-etiology-and-prevention-of-injuries-in-competitive-ice-speed-skatinglimited-current-evidence-multiple-future-priorities-a-scoping-review"},{"claim":"In elite youth long track skaters the knee had the highest repetitive injury burden (11 days lost per 1,000 h), followed by the thoracic spine.","source":"Hendricks, van de Water & Verhagen 2024, Br J Sports Med","url":"https://bjsm.bmj.com/content/58/14/785"},{"claim":"Reference levels for 30 s anaerobic power in national team skaters: senior men average 12.4-13.3 W/kg peak power, very high above 14.25.","source":"Sitkowski, Starczewski & Klusiewicz 2025, Biol Sport","url":"https://termedia.pl/Reference-levels-of-mean-and-peak-anaerobic-power-for-male-and-r-nfemale-long-track-speed-skaters,78,55023,1,0.html"}],"confidence":"moderate"},{"id":"taekwondo","name":"Taekwondo","aliases":["taekwondo","tae kwon do","tkd","kyorugi","sparring","poomsae","olympic taekwondo","itf taekwondo"],"group":"Combat","q":{"maxStrength":2,"power":3,"rotational":2,"unilateral":3,"upperPull":1,"upperPush":1,"lowerBody":3,"grip":0,"neck":2,"trunk":2,"mass":0},"prehab":["ankle","landing","copenhagen","hipFlex","neck"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"lower","energy":"Repeated short kicking exchanges inside three 2 min rounds with 1 min rest, so high anaerobic power on a moderate to high aerobic base.","summary":"Sparring is fast, repeated kicking on one leg with contact to the body and head, and most injuries hit the foot, knee and ankle. The plan builds single-leg strength and kicking power, hip flexor and adductor strength, ankle and landing control, neck strength, and keeps weight making safe.","evidence":[{"claim":"Lower-limb injuries are the most common in high-performance taekwondo, especially foot and knee; contusions lead, then sprains and ligament tears, mostly from direct contact.","source":"Epidemiology of injuries in high-performance taekwondo 2025, Cureus","url":"https://lida.sport-iat.de/djb/Record/4096204"},{"claim":"Amateur competition injury incidence was about 60 per 1,000 athlete-exposures, with about a third of injuries moderate to severe.","source":"Lystad, Graham & Poulos 2013, Br J Sports Med","url":"https://bjsm.bmj.com/content/47/7/441"},{"claim":"Rapid weight loss of 2-10% in the final days before weigh-in is common in combat sports and has documented health harms.","source":"Artioli et al. 2016, Sports Med","url":"https://www.iat.uni-leipzig.de/datenbanken/iks/dfb-fechten/Record/4042943"}],"confidence":"moderate"},{"id":"waterpolo","name":"Water polo","aliases":["water polo","waterpolo","polo","centre forward","hole set","water polo goalkeeper"],"group":"Team court","q":{"maxStrength":2,"power":3,"rotational":3,"unilateral":1,"upperPull":3,"upperPush":2,"lowerBody":2,"grip":2,"neck":1,"trunk":3,"mass":2},"prehab":["shoulderER","scap","tspine","copenhagen","trunkLat"],"season":{"off":3,"pre":2,"in":2},"avoidBefore":"upper","energy":"An aerobic base carrying repeated bursts of about 7 s (sprint swims, wrestling, shots) with work:rest near 1:1.6.","summary":"Water polo is repeated sprint swimming, wrestling and overhead shooting while treading water, and the shoulder takes most of the training injuries. The plan builds pulling strength, throwing and rotational power, adductor strength for the eggbeater, and a shoulder programme that never drops out in season.","evidence":[{"claim":"Match play is highly intermittent: bouts average 7.4 s with work:rest about 1:1.6; centre players wrestle about twice as much as outside players.","source":"D'Auria & Gabbett 2008, Int J Sports Physiol Perform","url":"https://acuresearchbank.acu.edu.au/item/8q951/a-time-motion-analysis-of-international-women-s-water-polo-match-play"},{"claim":"Shoulder injury rates range from 24% to 51% across studies and shoulder problems are more likely to become chronic than other water polo injuries.","source":"Miller et al. 2018, J Sci Med Sport","url":"https://research-repository.griffith.edu.au/items/613fee5f-b583-5344-8b8a-dc6a16673950"},{"claim":"Low pre-season shoulder rotation strength (external rotation at or below 12.5% body weight) and loss of dominant shoulder rotation range predicted later shoulder injury in sub-elite players.","source":"Hams et al. 2019, Phys Ther Sport","url":"https://research-repository.griffith.edu.au/items/7824fdf1-2dd8-429f-9029-6dc1851e6a52"}],"confidence":"moderate"}]};
